#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
layout(std140) uniform v_buffer0 {
	vec4 v_cb0[8];
} _v_buffer0;
layout(std140) uniform v_buffer1 {
	vec4 v_cb1;
} _v_buffer1;
layout(std140) uniform v_buffer2 {
	vec4 v_cb2[4];
} _v_buffer2;
layout(std140) uniform v_buffer3 {
	vec4 v_cb3[5];
} _v_buffer3;
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
in highp vec2 in_TEXCOORD1;
in highp vec4 in_COLOR0;
out highp vec2 vs_TEXCOORD0;
out highp vec2 vs_TEXCOORD1;
out highp vec2 vs_TEXCOORD2;
out highp vec4 vs_COLOR0;
vec4 u_xlat0;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * _v_buffer2.v_cb2[1];
    u_xlat0 = _v_buffer2.v_cb2[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = _v_buffer2.v_cb2[2] * in_POSITION0.zzzz + u_xlat0;
    gl_Position = _v_buffer2.v_cb2[3] * in_POSITION0.wwww + u_xlat0;
    u_xlat0.xy = _v_buffer0.v_cb0[3].xy * _v_buffer1.v_cb1.xx + in_TEXCOORD0.xy;
    vs_TEXCOORD1.xy = u_xlat0.xy * _v_buffer0.v_cb0[3].zz;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy * _v_buffer0.v_cb0[7].xy + _v_buffer0.v_cb0[7].zw;
    vs_TEXCOORD2.xy = in_TEXCOORD1.xy * _v_buffer0.v_cb0[7].xy + _v_buffer0.v_cb0[7].zw;
    u_xlat0 = _v_buffer3.v_cb3[4] * vec4(2.0, 2.0, 2.0, 2.0) + _v_buffer0.v_cb0[1];
    u_xlat0 = u_xlat0 + (-in_COLOR0);
    vs_COLOR0 = _v_buffer0.v_cb0[6].yyyy * u_xlat0 + in_COLOR0;
    return;
}

995a8064ab6bc26b6da1b230f7c6dcac8cd08a92.source:
#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
layout(std140) uniform f_buffer0 {
	vec4 f_cb0[7];
} _f_buffer0;
uniform highp sampler2D f_t0TEX_with_SMPf_s0;
uniform highp sampler2D f_t0;
uniform highp sampler2D f_t1TEX_with_SMPf_s2;
uniform highp sampler2D f_t1;
uniform highp sampler2D f_t2TEX_with_SMPf_s1;
uniform highp sampler2D f_t2;
in highp vec2 vs_TEXCOORD0;
in highp vec2 vs_TEXCOORD1;
in highp vec2 vs_TEXCOORD2;
in highp vec4 vs_COLOR0;
layout(location = 0) out highp vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
void main()
{
    u_xlat0 = texture(f_t1TEX_with_SMPf_s2, vs_TEXCOORD1.xy);
    u_xlat0.xyz = (-u_xlat0.xyz) + _f_buffer0.f_cb0[6].xxx;
    u_xlat1 = texture(f_t0TEX_with_SMPf_s0, vs_TEXCOORD0.xy);
    u_xlat0.xyz = (-u_xlat0.xyz) * u_xlat0.xyz + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat0.xyz + _f_buffer0.f_cb0[3].www;
    u_xlat0.xyz = u_xlat0.xyz * _f_buffer0.f_cb0[5].xyz;
    u_xlat1.xyz = (-u_xlat0.xyz) * _f_buffer0.f_cb0[4].xxx + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat0.xyz * _f_buffer0.f_cb0[4].xxx;
    u_xlat0.xyz = u_xlat1.www * u_xlat1.xyz + u_xlat0.xyz;
    u_xlat1 = texture(f_t2TEX_with_SMPf_s1, vs_TEXCOORD2.xy);
    u_xlat2.xyz = u_xlat0.xyz * u_xlat1.xyz + vec3(0.150000006, 0.150000006, 0.150000006);
    u_xlat0.xyz = u_xlat0.xyz * u_xlat1.xyz;
    u_xlat1.xyz = u_xlat2.xyz * vs_COLOR0.xyz;
    SV_Target0.xyz = min(u_xlat0.xyz, u_xlat1.xyz);
    SV_Target0.w = 1.0;
    return;
}
